solution.code:
function queryCount(plan) {
  const strategy = plan.strategy;
  if (strategy === 'lazy') return 1 + plan.rootRows * plan.navigations;
  if (strategy === 'split') return 1 + plan.navigations;
  if (strategy === 'include') return 1;
  if (strategy === 'none') return 1;
  return -1;
}

